"""Explicit serial capacity sharing without increasing any durable budget."""

import json

from .domain import DomainError

SERIAL_CAPACITY_VERSION = "serial-capacity-v1"


def validate_serial_policy(graph):
    policy = graph.get("serial_capacity_policy")
    if policy is None:
        return None
    if (
        not isinstance(policy, dict)
        or set(policy) != {"version", "shared_reserve_tokens"}
        or policy["version"] != SERIAL_CAPACITY_VERSION
        or type(policy["shared_reserve_tokens"]) is not int
        or not 1 <= policy["shared_reserve_tokens"] <= 1000000
        or graph.get("max_cost_microunits") is not None
        or graph.get("cost_currency") is not None
    ):
        raise DomainError("Serial capacity requires an explicit bounded token-only reserve")
    nodes = graph["nodes"]
    keys = {node["key"] for node in nodes}
    edges = graph["edges"]
    incoming, outgoing = dict.fromkeys(keys, 0), dict.fromkeys(keys, 0)
    for edge in edges:
        if (
            edge["condition"] != "success"
            or edge["source"] not in keys
            or edge["target"] not in keys
        ):
            raise DomainError("Serial capacity requires one strict success chain")
        incoming[edge["target"]] += 1
        outgoing[edge["source"]] += 1
    if (
        len(nodes) < 2
        or len(edges) != len(nodes) - 1
        or max(incoming.values(), default=0) > 1
        or max(outgoing.values(), default=0) > 1
        or sum(value == 0 for value in incoming.values()) != 1
        or sum(value == 0 for value in outgoing.values()) != 1
    ):
        raise DomainError("Serial capacity requires one strict success chain")
    reserve = graph.get("coordination_reserve_tokens")
    if (
        type(reserve) is not int
        or reserve < (graph["max_total_tokens"] + 9) // 10
        or sum(node["budget_tokens"] for node in nodes) + policy["shared_reserve_tokens"] + reserve
        > graph["max_total_tokens"]
    ):
        raise DomainError(
            "Serial baselines, one shared reserve and coordination exceed original cap"
        )
    return dict(policy)


def node_execution_limit(graph, node):
    policy = validate_serial_policy(graph)
    return node["budget_tokens"] + (policy["shared_reserve_tokens"] if policy else 0)


def serial_start_allowance(store, connection, quest, plan, node, member, ledger=None):
    """Read-only admission from settled usage; caller retains its execution fence.

    The returned ceiling is a subset of the approved per-member maximum. It is
    not a new allocation, charge, refund, predicted usage or permission to run.
    """
    from .capacity_preflight import coordination_budget_snapshot

    plan = dict(plan)
    graph = json.loads(plan["graph_json"]) if "graph_json" in plan else plan
    policy = validate_serial_policy(graph)
    if policy is None:
        raise DomainError("Serial Worker requires its approved serial capacity policy")
    key = member["task_node_key"]
    contracts = [item for item in graph["nodes"] if item["key"] == key]
    if len(contracts) != 1:
        raise DomainError("Serial Worker task contract unavailable")
    contract = contracts[0]
    if ledger is None or str(ledger.path) != str(store.path):
        raise DomainError("Serial Worker requires the original durable Gateway budget ledger")
    maximum = node_execution_limit(graph, contract)
    if (
        member.get("serial_capacity_policy") != policy
        or member.get("execution_token_limit") != maximum
        or member["estimated_tokens"] != contract["budget_tokens"]
    ):
        raise DomainError("Serial member capacity differs from its approved plan")
    if connection.execute(
        "SELECT 1 FROM worker_runs WHERE quest_id=? AND state IN ('running','review_pending') LIMIT 1",
        (quest["id"],),
    ).fetchone():
        raise DomainError("Serial capacity cannot overlap an active Worker or review")
    model_table = connection.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name='model_budget_attempts'"
    ).fetchone()
    if (
        model_table
        and connection.execute(
            "SELECT 1 FROM model_budget_attempts WHERE quest_id=? AND "
            "(state!='settled' OR input_charged IS NULL OR output_charged IS NULL) LIMIT 1",
            (quest["id"],),
        ).fetchone()
    ):
        raise DomainError("Serial capacity requires every prior model attempt fully settled")
    states = {
        row["node_key"]: row["status"]
        for row in connection.execute(
            "SELECT node_key,status FROM task_nodes WHERE plan_id=?", (plan["id"],)
        )
    }
    pending = {item["key"] for item in graph["nodes"] if states.get(item["key"]) != "succeeded"}
    if key not in pending:
        raise DomainError("Serial Worker node already completed")
    if any(
        edge["target"] == key and states.get(edge["source"]) != "succeeded"
        for edge in graph["edges"]
    ):
        raise DomainError("Serial Worker success predecessor is not completed")
    future = sum(item["budget_tokens"] for item in graph["nodes"] if item["key"] in pending - {key})
    budget = coordination_budget_snapshot(connection, store, quest["id"], graph, ledger)
    available = max(0, budget["max_worker_allocations_now"] - future)
    observation = graph.get("capacity_contract", {}).get("nodes", {}).get(key, {})
    minimum = observation.get("minimum_node_tokens")
    if type(minimum) is not int or minimum < 1 or available < minimum:
        raise DomainError(
            "Serial remaining budget cannot fund current full cycle and future baselines"
        )
    return {
        "version": SERIAL_CAPACITY_VERSION,
        "execution_token_limit": min(maximum, available),
        "approved_execution_token_limit": maximum,
        "baseline_tokens": contract["budget_tokens"],
        "shared_reserve_tokens": policy["shared_reserve_tokens"],
        "minimum_current_cycle": minimum,
        "future_baseline_tokens": future,
        "budget_snapshot": budget,
        "allocation_policy": "Charge each approved baseline and this shared reserve once; no refund of spent, allocated or unresolved amounts.",
    }

from pydantic import BaseModel, ConfigDict, Field, model_validator


class NodeCapacityBounds(BaseModel):
    """Explicit opt-in bounds; unknown future artifact sizes are never zero."""

    model_config = ConfigDict(extra="forbid", strict=True)
    max_source_receipt_bytes: int = Field(ge=1, le=65536)
    max_artifact_bytes: int = Field(ge=1, le=32768)
    max_delivery_bytes: int = Field(ge=1, le=32768)


class SerialCapacityPolicy(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    version: Literal["serial-capacity-v1"]
    shared_reserve_tokens: int = Field(ge=1, le=1000000)


class TaskNodeProposal(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    key: str = Field(min_length=1, max_length=100, pattern=r"^[A-Za-z0-9_-]+$")
    objective: str = Field(min_length=1, max_length=2000)
    success_criteria: list[str] = Field(min_length=1, max_length=20)
    budget_tokens: int = Field(ge=1, le=1000000)
    required_capabilities: dict[str, float] = Field(default_factory=dict, max_length=32)
    expected_artifact: str | None = Field(default=None, max_length=2000)
    max_attempts: int = Field(default=1, ge=1, le=10)
    allowed_tools: list[str] = Field(default_factory=list, max_length=32)
    required_input_paths: list[str] | None = Field(default=None, max_length=32)
    required_predecessor_deliveries: list[str] | None = Field(default=None, max_length=8)
    capacity_bounds: NodeCapacityBounds | None = None

    @model_validator(mode="after")
    def criteria_valid(self):
        if any(not item.strip() or len(item) > 1000 for item in self.success_criteria):
            raise ValueError("Invalid success criterion")
        if any(
            not key.strip() or not 0 <= value <= 100
            for key, value in self.required_capabilities.items()
        ):
            raise ValueError("Invalid required capability")
        from .tool_domain import CONTRACTS

        known = {contract.name for contract in CONTRACTS}
        if len(set(self.allowed_tools)) != len(self.allowed_tools) or any(
            name not in known for name in self.allowed_tools
        ):
            raise ValueError("Unknown or duplicate tool")
        deliveries = self.required_predecessor_deliveries or []
        import re

        if len(deliveries) != len(set(deliveries)) or any(
            not re.fullmatch(r"[A-Za-z0-9_-]{1,100}", key) for key in deliveries
        ):
            raise ValueError("Invalid or duplicate completed-delivery source")
        if deliveries and "worker_read_completed_delivery" not in self.allowed_tools:
            raise ValueError("Completed deliveries require the explicit Core read tool")
        return self


class TaskEdgeProposal(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    source: str = Field(min_length=1, max_length=100)
    target: str = Field(min_length=1, max_length=100)
    condition: Literal["success", "failure", "always"]


class GraphProposal(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    nodes: list[TaskNodeProposal] = Field(min_length=1, max_length=128)
    edges: list[TaskEdgeProposal] = Field(max_length=512)
    max_total_tokens: int = Field(default=1000000, ge=1, le=1000000)
    max_cost_microunits: int | None = Field(default=None, ge=0)
    cost_currency: str | None = Field(default=None, pattern=r"^[A-Z]{3}$")
    max_duration_seconds: int | None = Field(default=None, ge=1)
    execution_constraints: dict | None = None
    capacity_contract: dict | None = None
    coordination_reserve_tokens: int | None = Field(default=None, ge=1, le=1000000)
    revision_lineage: dict | None = None
    hierarchical_expansions: list[dict] | None = Field(default=None, max_length=8)
    serial_capacity_policy: SerialCapacityPolicy | None = None

    @model_validator(mode="after")
    def graph_valid(self):
        if (self.max_cost_microunits is None) != (self.cost_currency is None):
            raise ValueError("A cost limit requires an explicit currency")
        keys = [node.key for node in self.nodes]
        if (
            len(keys) != len(set(keys))
            or sum(node.budget_tokens for node in self.nodes) > self.max_total_tokens
        ):
            raise ValueError("Duplicate node or total budget exceeded")
        incoming = dict.fromkeys(keys, 0)
        outgoing = {key: [] for key in keys}
        edges = set()
        for edge in self.edges:
            pair = (edge.source, edge.target)
            if edge.source not in incoming or edge.target not in incoming or pair in edges:
                raise ValueError("Invalid graph edge")
            edges.add(pair)
            incoming[edge.target] += 1
            outgoing[edge.source].append(edge.target)
        ready = [key for key, count in incoming.items() if count == 0]
        count = 0
        while ready:
            node = ready.pop()
            count += 1
            for child in outgoing[node]:
                incoming[child] -= 1
                if incoming[child] == 0:
                    ready.append(child)
        if count != len(keys):
            raise ValueError("Graph contains a cycle")
        for node in self.nodes:
            parents = {
                edge.source
                for edge in self.edges
                if edge.target == node.key and edge.condition == "success"
            }
            if set(node.required_predecessor_deliveries or []) - parents:
                raise ValueError("Completed delivery must be a direct success predecessor")
        if self.serial_capacity_policy is not None:
            from .budget_policy import validate_serial_policy

            validate_serial_policy(self.model_dump())
        return self


class CapabilityWire(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    name: str = Field(min_length=1, max_length=100)
    minimum: float = Field(ge=0, le=100, allow_inf_nan=False)

