from forge_core.review_envelope import review_packet_sizes
from forge_core.settings import Workspace


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def rows(connection, sql, args=()):
    return [dict(row) for row in connection.execute(sql, args)]


def select(data, keys):
    return {key: data[key] for key in keys if key in data}


def timestamp(value):
    return datetime.fromisoformat(value).timestamp()


def conservative_tokens(attempt):
    return sum(
        attempt[charged] if attempt[charged] is not None else attempt[reserved]
        for charged, reserved in (
            ("input_charged", "input_reserved"),
            ("output_charged", "output_reserved"),
        )
    )


def allocation_audit(connection, record, workers, attempts, events):
    """Reconstruct held baseline/pool allocations without calling runtime policy."""
    plans = {row["id"]: row for row in rows(connection, "SELECT * FROM quest_plans")}
    teams = {
        row["proposal_digest"]: row
        for row in rows(connection, "SELECT * FROM team_proposals")
    }
    capsules = {
        row["run_id"]: json.loads(row["capsule_json"])
        for row in rows(connection, "SELECT * FROM worker_capsules")
    }
    opening = rows(connection, "SELECT * FROM model_budget_opening")
    ledgers = rows(
        connection, "SELECT * FROM worker_budget_ledger ORDER BY scope,scope_id"
    )
    workspace_id = connection.execute(
        "SELECT id FROM workspace WHERE singleton=1"
    ).fetchone()[0]
    expected, markers, serial, errors = defaultdict(lambda: [0, 0]), {}, [], []
    original_cap = {"L1": 180000, "L2": 360000, "L3": 630000}[record["level"]]
    cap_valid = (
        record["scenario"]["limits"]["max_total_tokens"] == original_cap
        and record["runtime_settings"]["model_token_limit"] == original_cap
    )
    for worker in workers:
        try:
            plan, team = plans[worker["plan_id"]], teams[worker["team_digest"]]
            graph, body = json.loads(plan["graph_json"]), json.loads(team["body_json"])
            member = body["members"][worker["member_index"]]
            node = next(
                item for item in graph["nodes"] if item["key"] == worker["node_key"]
            )
            binding = (
                hashlib.sha256(_json(graph).encode()).hexdigest()
