def source_snapshot(workspace, quest_id):
    """Exact eligible memory rows and their source rows, through read-only handles."""
    with readonly(workspace) as db:
        refs = {row[0] for row in db.execute("SELECT source_ref FROM memory_source_index WHERE quest_id=?", (quest_id,))}
        refs.update("constraint:" + row[0] for row in db.execute("SELECT id FROM constraint_records WHERE quest_id=?", (quest_id,)))
        refs.update("memory:" + row[0] for row in db.execute("SELECT id FROM memories WHERE related_quest_ids LIKE ?", ("%" + quest_id + "%",)))
        quest = dict(db.execute("SELECT * FROM quests WHERE id=?", (quest_id,)).fetchone())
        user_id = json.loads(quest["metadata"])["original_request_message_id"]
        refs.add("message:" + user_id)
        original_user = dict(db.execute("SELECT * FROM messages WHERE id=?", (user_id,)).fetchone())
        raw = {}
        for ref in refs:
            table, column, identity = ("memory_source_index", "source_ref", ref)
            if ref.startswith("constraint:"):
                table, column, identity = "constraint_records", "id", ref[11:]
            elif ref.startswith("memory:"):
                table, column, identity = "memories", "id", ref[7:]
            elif ref.startswith("message:"):
                table, column, identity = "messages", "id", ref[8:]
            row = db.execute(f"SELECT * FROM {table} WHERE {column}=?", (identity,)).fetchone()
            if row:
                raw[ref] = {"table": table, "row": dict(row), "row_sha256": sha(canonical(dict(row)).encode())}
    service = MemoryService(_ReadOnlyStore(Path(workspace).resolve()))
    eligible = {}
    for ref in sorted(refs):
        items = service.retrieve_context("", source_refs=[ref], exact_source_refs=True, limit=1, max_bytes=65536)["items"]
        if items:
            eligible[ref] = {"item": items[0], "item_sha256": sha(canonical(items[0]).encode()), "raw": raw.get(ref)}
    return {"quest_id": quest_id, "original_user": original_user, "original_user_sha256": sha(canonical(original_user).encode()), "eligible": eligible}


